package br.com.onda;
import android.content.Context;import android.net.Uri;import java.util.List;import java.util.Collections;
import android.graphics.*;import android.media.*;import android.os.SystemClock;import java.io.*;import java.nio.*;
/** Explicit six-second pan/zoom montage, not generative text-to-video. */
final class LocalAiVideo {
 static void create(File card,File output,LocalAiModels.Cancel token)throws IOException{create(null,card,Collections.emptyList(),output,token);}
 static void create(Context context,File card,List<Uri> photos,File output,LocalAiModels.Cancel token)throws IOException{Bitmap source=null,frame=null;MediaCodec codec=null;boolean complete=false;DownloadMux.Cancel cancel=token::check;try(PhotoCodecOutput sink=new PhotoCodecOutput(output)){
  source=photos.isEmpty()?BitmapFactory.decodeFile(card.getPath()):LocalAiPhotos.load(context,photos.get(0),1280,token);if(source==null)throw new IOException("Crie um cartão antes de animar.");int width=320,height=400;frame=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(frame);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);int[] rgb=new int[width*height];PhotoVideo.Pixels pixels=new PhotoVideo.Pixels(width,height);
  MediaFormat format=MediaFormat.createVideoFormat("video/avc",width,height);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);format.setInteger(MediaFormat.KEY_BIT_RATE,600000);format.setInteger(MediaFormat.KEY_FRAME_RATE,4);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,2);codec=MediaCodec.createEncoderByType("video/avc");codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();long indexFrame=0,frames=photos.isEmpty()?24L:(long)photos.size()*12L;int photoIndex=0;boolean ended=false;long last=SystemClock.elapsedRealtime();while(!sink.ended){cancel.check();if(SystemClock.elapsedRealtime()-last>30000)throw new IOException("O codificador parou de responder.");if(!ended){int index=codec.dequeueInputBuffer(10000);if(index>=0){if(indexFrame>=frames){codec.queueInputBuffer(index,0,0,frames*250000L,MediaCodec.BUFFER_FLAG_END_OF_STREAM);ended=true;}else{if(!photos.isEmpty()&&(int)(indexFrame/12)!=photoIndex){source.recycle();source=null;photoIndex=(int)(indexFrame/12);source=LocalAiPhotos.load(context,photos.get(photoIndex),1280,token);}float progress=photos.isEmpty()?indexFrame/23f:(indexFrame%12)/11f,zoom=1f+.08f*(float)(.5-.5*Math.cos(progress*Math.PI));float dx=(width-width*zoom)/2,dy=(height-height*zoom)/2;canvas.drawColor(Color.BLACK);if(photos.isEmpty())canvas.drawBitmap(source,null,new RectF(dx,dy,dx+width*zoom,dy+height*zoom),paint);else{float fit=Math.min(width/(float)source.getWidth(),height/(float)source.getHeight()),w=source.getWidth()*fit,h=source.getHeight()*fit;canvas.drawBitmap(source,null,new RectF((width-w)/2,(height-h)/2,(width+w)/2,(height+h)/2),paint);}frame.getPixels(rgb,0,width,0,0,width,height);yuv(rgb,pixels,cancel);Image image=codec.getInputImage(index);if(image==null||image.getPlanes().length!=3)throw new IOException("O aparelho não oferece um codificador compatível para o clipe.");Image.Plane[] planes=image.getPlanes();PhotoVideo.plane(planes[0],pixels.y,width,height);PhotoVideo.plane(planes[1],pixels.u,width/2,height/2);PhotoVideo.plane(planes[2],pixels.v,width/2,height/2);ByteBuffer buffer=codec.getInputBuffer(index);codec.queueInputBuffer(index,0,buffer==null?width*height*3/2:buffer.capacity(),indexFrame*250000L,0);indexFrame++;}last=SystemClock.elapsedRealtime();}}if(sink.drain(codec,cancel))last=SystemClock.elapsedRealtime();}sink.finish();complete=true;
 }catch(RuntimeException|OutOfMemoryError e){throw new IOException("Não foi possível criar o clipe neste aparelho. O cartão continua disponível.",e);}finally{PhotoCodecOutput.release(codec);if(source!=null)source.recycle();if(frame!=null)frame.recycle();if(!complete)output.delete();}}
 private static void yuv(int[] rgb,PhotoVideo.Pixels out,DownloadMux.Cancel cancel)throws IOException{int width=out.width,height=out.height;for(int row=0;row<height;row++){cancel.check();for(int col=0;col<width;col++){int c=rgb[row*width+col],r=(c>>16)&255,g=(c>>8)&255,b=c&255;out.y[row*width+col]=(byte)PhotoVideo.clamp(((66*r+129*g+25*b+128)>>8)+16);}}for(int row=0;row<height;row+=2)for(int col=0;col<width;col+=2){int r=0,g=0,b=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){int c=rgb[(row+dy)*width+col+dx];r+=(c>>16)&255;g+=(c>>8)&255;b+=c&255;}r/=4;g/=4;b/=4;int i=row/2*(width/2)+col/2;out.u[i]=(byte)PhotoVideo.clamp(((-38*r-74*g+112*b+128)>>8)+128);out.v[i]=(byte)PhotoVideo.clamp(((112*r-94*g-18*b+128)>>8)+128);}}
}
